typedef unsigned int u_int;
typedef unsigned int u_long128 __attribute__((mode(TI)));

struct sceIpuDmaEnv
{
    u_int d4madr;
    u_int d4tadr;
    u_int d4qwc;
    u_int d4chcr;
    u_int d3madr;
    u_int d3qwc;
    u_int d3chcr;
    u_int ipubp;
    u_int ipuctrl;
};

typedef struct
{
    long pts;
    long dts;
    int pos;
    int len;
} TimeStamp;

typedef struct
{
    u_long128 *data;
    u_long128 *tag;
    int n;
    int dmaStart;
    int dmaN;
    int readBytes;
    int buffSize;
    sceIpuDmaEnv env;
    int sema;
    int isActive;
    long totalBytes;
    TimeStamp *ts;
    int n_ts;
    int count_ts;
    int wt_ts;
} ViBuf;

extern "C" int WaitSema(int sema);
extern "C" int SignalSema(int sema);
static int viBufModifyPts(ViBuf *f, TimeStamp *new_ts);

__asm__(".equ WaitSema, 0x003DB6A0");
__asm__(".equ SignalSema, 0x003DB680");
__asm__(".equ viBufModifyPts__FP5ViBufP9TimeStamp, 0x0038A8D8");

static int viBufPutTs( ViBuf* f, TimeStamp* ts )
{
    int ret = 0;

    WaitSema( f->sema );
    if( f->count_ts < f->n_ts )
    {
        viBufModifyPts( f, ts );
        if( ts->pts >= 0 || ts->dts >= 0 )
        {
            f->ts[f->wt_ts].pts = ts->pts;
            f->ts[f->wt_ts].dts = ts->dts;
            f->ts[f->wt_ts].pos = ts->pos;
            f->ts[f->wt_ts].len = ts->len;
            f->count_ts++;
            f->wt_ts = (f->wt_ts + 1) % f->n_ts;
        }
        ret = 1;
    }
    SignalSema( f->sema );
    return ret;
}
